settings.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400%3B500%3B600%3B700&display=swap');

/* tb-ai-palette */ .device-page { --canvas: var(--tb-ai-canvas, #F7F8FA); --surface: var(--tb-ai-surface, #FFFFFF); --text: var(--tb-ai-text, rgba(0,0,0,0.87)); --text-secondary: var(--tb-ai-text-secondary, rgba(0,0,0,0.54)); --border: var(--tb-ai-border, rgba(0,0,0,0.12)); --primary: var(--tb-ai-primary, var(--tb-primary-500, #00695C)); --on-primary: var(--tb-ai-on-primary, var(--tb-primary-contrast-500, #FFFFFF)); --accent: var(--tb-ai-accent, var(--tb-accent-500, #FF5722)); }

tb-icon {
  width: 1em;
  height: 1em;
  min-width: 1em;
  min-height: 1em;
  font-size: 24px;
  line-height: 1;
}

.device-page {
  --tb-ai-font: 'Inter',sans-serif;
  font-family: var(--tb-ai-font);
  --tb-ai-card-border: 1px solid var(--border);
  --tb-ai-card-radius: 12px;
  --tb-ai-card-shadow: 0 1px 3px rgba(0,0,0,0.05);
  --tb-ai-card-padding: 16px;
  --tb-ai-card-title-size: 14px;
  --tb-ai-card-title-weight: 600;
  --tb-ai-card-title-color: var(--text);
  --tb-ai-card-title-line-height: 20px;
  --tb-ai-table-header-size: 12px;
  --tb-ai-table-header-weight: 600;
  --tb-ai-table-header-color: var(--text-secondary);
  --tb-ai-table-cell-size: 13px;
  --tb-ai-table-cell-weight: 400;
  --tb-ai-table-cell-color: var(--text);
  --tb-ai-table-divider-color: var(--border);
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: var(--canvas);
  color: var(--text);
  overflow-y: auto;
  container: page/inline-size;
}

.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.top-bar__left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.top-bar__right {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.device-title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.device-icon {
  font-size: 24px;
  color: var(--primary);
}

.device-name {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: color-mix(in srgb,var(--text-secondary) 12%,transparent);
  color: var(--text-secondary); white-space: nowrap; flex: none;
}

.status-badge .status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
}

.status-badge--online {
  background: color-mix(in srgb,#4CAF50 15%,transparent);
  color: #4CAF50;
}

.status-badge--offline {
  background: color-mix(in srgb,#EF5350 15%,transparent);
  color: #EF5350;
}

.last-updated {
  font-size: 12px;
  color: var(--text-secondary);
}

.theme-toggle-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

.alarm-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid transparent;
}

.alarm-banner--ok {
  background: color-mix(in srgb,#4CAF50 10%,transparent);
  border-color: color-mix(in srgb,#4CAF50 25%,transparent);
  color: var(--text);
}

.alarm-banner--ok .alarm-banner__icon {
  color: #4CAF50;
  font-size: 24px;
}

.alarm-banner--warning {
  background: color-mix(in srgb,#FFA726 12%,transparent);
  border-color: color-mix(in srgb,#FFA726 30%,transparent);
  color: var(--text);
}

.alarm-banner--warning .alarm-banner__icon {
  color: #FFA726;
  font-size: 24px;
}

.alarm-banner__headline {
  font-size: 14px;
  font-weight: 600;
}

.alarm-banner__sub {
  font-size: 12px;
  color: var(--text-secondary);
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(210px,1fr));
  gap: 14px;
}

.kpi-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
}

.kpi-card--alert {
  border-color: color-mix(in srgb,#FFA726 40%,transparent);
}

.kpi-card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--text-secondary); flex-wrap: wrap;
}

.kpi-card__label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.kpi-card__icon {
  font-size: 20px;
  color: var(--primary);
}

.kpi-card__body {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.kpi-card__value--status {
  font-size: 20px;
  font-weight: 600;
}

.kpi-card__unit {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
}

.kpi-card__footer {
  display: flex;
  align-items: center;
  margin-top: auto;
}

.pill-info {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
}

.pill-alert {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px; white-space: nowrap; flex: none;
}

.pill-alert tb-icon {
  font-size: 14px;
}

.pill-alert--ok {
  color: #4CAF50;
  background: color-mix(in srgb,#4CAF50 15%,transparent);
}

.pill-alert--warn {
  color: #FFA726;
  background: color-mix(in srgb,#FFA726 15%,transparent);
}

.pill-alert--crit {
  color: #EF5350;
  background: color-mix(in srgb,#EF5350 15%,transparent);
}

.info-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  background: var(--surface);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
}

.info-strip__item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.info-strip__label {
  color: var(--text-secondary);
  font-weight: 500;
}

.info-strip__val {
  color: var(--text);
  font-weight: 600;
}

.info-strip__divider {
  width: 1px;
  height: 14px;
  background: var(--border);
}

.tabs-section {
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
  min-height: 0;
}

.tabs-bar-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.tabs-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  max-width: 100%;
  flex: none; min-width: 0; overflow-y: hidden; padding-bottom: 2px; margin-bottom: -2px;
}

.tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.tab-btn:hover {
  background: color-mix(in srgb,var(--primary) 6%,transparent);
  color: var(--text);
}

.tab-btn.is-active {
  background: color-mix(in srgb,var(--primary) 12%,transparent);
  border-color: color-mix(in srgb,var(--primary) 20%,transparent);
  color: var(--primary);
}

.tab-content {
  flex: 1;
  min-height: 480px;
}

.embed-wrapper {
  width: 100%;
  height: 100%;
  min-height: 500px;
  height: 650px;
}

.embed-wrapper tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

/* tb-ai-toggle-pinned */
.top-bar { flex-wrap: wrap; align-items: flex-start; }
.top-bar > * { min-width: 0; flex: 1 1 240px; }
.top-bar > .top-bar__right { flex: none; width: auto; max-width: 100%; margin-left: auto; }
.top-bar { position: relative; padding-right: calc(0px + 48px); }
.top-bar :has([data-tb-ai-theme-toggle]) { position: static; }
.top-bar [data-tb-ai-theme-toggle] { position: absolute; top: 0px; right: 0px; margin: 0; z-index: 1; }

/* tb-ai-whole-sections */
.tabs-section { flex: 1 0 auto; min-height: auto; }

/* tb-ai-fill */
.tabs-section { flex: 1 0 auto; display: flex; flex-direction: column; }
.tab-content { flex: 1 0 auto; display: flex; flex-direction: column; }
.embed-wrapper { flex: 1 0 auto; height: auto; min-height: 650px; }

/* tb-ai-responsive */
@media (max-width: 1279px) {
  .embed-wrapper:has(> tb-dashboard-state[stateid="monitoring"]) { height: 1930px; min-height: 1930px; }
}
@media (max-width: 959px) {
  .embed-wrapper:has(> tb-dashboard-state[stateid="alarms"]) { height: 570px; min-height: 570px; }
}

